import React from 'react';
import DataTable, {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableHeader,
  TableRow,
} from 'carbon-components-react';

const initialRows = [
  {
    id: 'a',
    name: 'Program 1',
    description: 'Description here',
    status: 'Enrolled',
    startDate: '01/01/2017',
  },
  {
    id: 'b',
    name: 'Program 2',
    description: 'Description here',
    status: 'Complete',
    startDate: '01/01/2017',
  },
];

const headers = [
  { key: 'name', header: 'Name' },
  { key: 'description', header: 'Description' },
  { key: 'status', header: 'Status' },
  { key: 'startDate', header: 'Start Date' },
];

function App() {
  return (
    <DataTable
      rows={initialRows}
      headers={headers}
      size="tall"
      render={({ rows, headers, getHeaderProps }) => (
        <TableContainer title="DataTable">
          <Table>
            <TableHead>
              <TableRow>
                {headers.map((header) => (
                  <TableHeader {...getHeaderProps({ header })} isSortable>
                    {header.header}
                  </TableHeader>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {rows.map((row) => (
                <TableRow key={row.id}>
                  {row.cells.map((cell) => (
                    <TableCell key={cell.id}>{cell.value}</TableCell>
                  ))}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    />
  );
}

export default App;
